                 DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
             }));
             return;
         }

         writer.WriteLine($"{ReviewCrossRuntimeCommand.CommandName} request: refused ({cause})");
         writer.WriteLine($"- detail: {detail}");
         writer.WriteLine($"- fix: {fix}");
     }
